import zones from '../../../server/data/countryTimezones.json';

export interface CountryZone {
  id: string;
  en: string;
  fr: string;
  de: string;
  es: string;
}

/**
 * Country code → IANA zones. Data is `server/data/countryTimezones.json`,
 * generated by `scripts/generate-country-timezones.mjs` from tzdata `zone.tab`
 * (allow-list `iso3166.tab`). That file is the only copy: the server embeds
 * it and does not read `ui/`. A country with one zone uses that zone. A
 * country with several zones has no default.
 */
export const COUNTRY_ZONES: Record<string, readonly CountryZone[]> = zones;
